    // the terrace: wall line along the moat (the inlet to the west, the moat to the south), the terrace behind it
    const WL = [[-60.0, -11.2], [-30.4, -10.7], [-27.9, 6.7], [10.0, 9.2], [48.1, 11.8]];
    ishigaki(B.a(ISHI), WL, yW - 1.0, T, 1.5, 0.28, 1);
    for (let y = yW + 0.6; y < T - 0.4; y += 1.3){ const k = (y - (yW - 1.0))/(T - yW + 1.0), d = (1 - k)*(T - yW + 1.0)*0.28 + 0.05;
      const Q = WL.map((p, i) => { const a = WL[Math.max(0, i - 1)], b = WL[Math.min(WL.length - 1, i + 1)], L = Math.hypot(b[0] - a[0], b[1] - a[1]); return [p[0] - (b[1] - a[1])/L*d, p[1] + (b[0] - a[0])/L*d]; });
      for (let i = 0; i + 1 < Q.length; i++) quad(B.a(ISHI2), [Q[i][0], y, Q[i][1]], [Q[i + 1][0], y, Q[i + 1][1]], [Q[i + 1][0], y + 0.22, Q[i + 1][1]], [Q[i][0], y + 0.22, Q[i][1]]); }
    // the terrace top and its back / end walls (lower, they face the inner palace)
    const TP = [[-60.0, -11.2], [-30.4, -10.7], [-27.9, 6.7], [10.0, 9.2], [48.1, 11.8], [48.6, -6.0], [10.0, -8.0], [-2.0, -11.5], [-27.5, -11.5], [-33.0, -16.0], [-33.0, -22.0], [-60.0, -22.0]];
