    ring4(g, tc[0], tc[1], 14.6, 13.0, T + 2.2, 1.6, 1.2, 4, 3, WIN, 1.6);
    const y1 = eave(g, {x:tc[0], z:tc[1], y:T + 5.4, L:14.6, W:13.0, over:1.8, h:1.7, pw:1.3, lift:0.45, fas:0.35, n:6, col:ROOF});
    for (const s of [-1, 1]) dormer(g, R, s > 0 ? 0 : PI, 0, T + 5.5, 6.9, 5.4, 2.6, 3.6, ROOF, WH);
    LBox(g, 10.4, 4.6, 8.8, tc[0], y1 - 0.5, tc[1], WH);
    ring4(g, tc[0], tc[1], 10.4, 8.8, y1 + 1.0, 1.4, 1.1, 3, 2, WIN, 1.4);
    eave(g, {x:tc[0], z:tc[1], y:y1 + 4.1, L:10.4, W:8.8, over:1.7, h:2.8, gab:0.5, k:3.2, pw:1.25, lift:0.55, fas:0.35, n:6, col:ROOF, gcol:WH, ridge:0.3});
    for (const s of [-1, 1]) LBox(g, 0.5, 1.2, 0.35, tc[0] + s*3.6, y1 + 6.8, tc[1], '#4a5054');
