    prism(B.a(GRA), P, 0, 15.6, true); band(B.a(GRA2), P, 0, 3.6, 0.3); band(B.a(GRA2), P, 3.6, 4.1, 0.45);
    band(B.a(GRA2), P, 14.4, 15.6, 0.55); band(B.a(GRA), P, 15.6, 16.8, 0.05);
    ringWins(B.a(WIN), P, 1.0, 1, 3.0, 3.6, 1.2, 1.4, 4, 0.3);               // basement windows
    ringWins(B.a(WIN), P, 4.6, 2, 5.0, 3.6, 1.7, 3.5, 4, 0.5);               // the two main storeys
    ringFins(B.a(GRA2), P, 4.1, 14.4, 3.6, 0.55, 0.4, 6);                    // pilasters
